/** Strip BOM / zero-width chars — editors sometimes save secrets with invisible prefixes. */
function normalizeJwtSecretMaterial(raw: string): string {
  return raw
    .replace(/^\uFEFF/, "")
    .trim()
    .replace(/[\u200B-\u200D\uFEFF]/g, "");
}

